<template><ion-page><ion-header><ion-toolbar><ion-title><span class="toolbar-page-title">Meu perfil</span><span class="toolbar-brand-right">Task<span>Edu</span></span></ion-title></ion-toolbar></ion-header><ion-content><main class="page-container profile-page"><section class="profile-hero"><div class="avatar">{{iniciais}}</div><div><span class="role-badge" :class="usuario?.tipo">Conta de {{usuario?.tipo}}</span><h1>{{usuario?.nome}}</h1><p>{{usuario?.email}}</p></div></section><section class="profile-card"><div class="form-section-title"><span>✦</span><div><h2>Informações pessoais</h2><p>Mantenha seus dados acadêmicos atualizados.</p></div></div><form @submit.prevent="salvar"><ion-input v-model="nome" label="Nome completo" label-placement="stacked" fill="outline" required/><ion-input :value="usuario?.email" label="E-mail" label-placement="stacked" fill="outline" readonly/><ion-button type="submit" expand="block" :disabled="salvando">Salvar perfil</ion-button></form><ion-button expand="block" fill="outline" router-link="/alterar-senha">Alterar senha</ion-button><ion-button expand="block" fill="outline" :aria-pressed="escuro" @click="alternarTema"><ion-icon slot="start" :icon="escuro ? sunnyOutline : moonOutline"/>{{escuro ? 'Usar modo claro' : 'Usar modo escuro'}}</ion-button><ion-button expand="block" fill="outline" router-link="/sobre"><ion-icon slot="start" :icon="informationCircleOutline"/>Sobre nós</ion-button><ion-button class="logout-button" expand="block" fill="outline" color="danger" @click="sair"><ion-icon slot="start" :icon="logOutOutline"/>Sair da conta</ion-button></section></main></ion-content><BottomNav v-if="usuario" :tipo="usuario.tipo"/></ion-page></template>
<script setup lang="ts">import { computed,ref } from 'vue';import { useTheme } from '../composables/useTheme';const { escuro, alternarTema } = useTheme();import { useRouter } from 'vue-router';import { IonButton,IonContent,IonHeader,IonIcon,IonInput,IonPage,IonTitle,IonToolbar,toastController } from '@ionic/vue';import { sunnyOutline,moonOutline,informationCircleOutline,logOutOutline } from 'ionicons/icons';import BottomNav from '../components/BottomNav.vue';import { atualizarPerfil,getUsuarioAtual,logout,mensagemAuth } from '../services/auth.service';const router=useRouter(),usuario=getUsuarioAtual(),nome=ref(usuario.value?.nome||''),salvando=ref(false);const iniciais=computed(()=>usuario.value?.nome.split(' ').slice(0,2).map(p=>p[0]).join('').toUpperCase());async function salvar(){salvando.value=true;try{await atualizarPerfil({nome:nome.value});salvando.value=false;const toast=await toastController.create({message:'Perfil atualizado!',duration:1400,color:'success',position:'top'});await toast.present()}catch(e){const toast=await toastController.create({message:mensagemAuth(e),duration:3500,color:'danger'});await toast.present()}finally{salvando.value=false}}async function sair(){await logout();await router.replace('/login')}</script>
